type View = 'overview' | 'assets' | 'securebuild' | 'barriers' | 'evidence' | 'audit' | 'roadmap' | 'soc' | 'endpoints' | 'operations' | 'capabilities' | 'analyses' | 'lab' | 'forensics' | 'graph' | 'imports' | 'authorizations' | 'assessments';
type IconName = 'shield' | 'grid' | 'box' | 'code' | 'layers' | 'fingerprint' | 'activity' | 'arrow' | 'plus' | 'search' | 'refresh' | 'download' | 'upload' | 'close' | 'lock' | 'logout' | 'check' | 'chevron' | 'map' | 'menu';
const paths: Record<IconName, ReactNode> = {
  shield: <><path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/></>,
  grid: <><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></>,
  box: <><path d="m12 3 9 5v8l-9 5-9-5V8zM3 8l9 5 9-5M12 13v8M7.5 5.5l9 5"/></>,
  code: <><path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 20"/></>,
  layers: <><path d="m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5"/></>,
  fingerprint: <><path d="M4 10a8 8 0 0 1 16 0v3M7 13v-3a5 5 0 0 1 10 0v4c0 3-1 5-3 7M10 18c1-2 1-4 1-6v-2a1 1 0 0 1 2 0v4c0 2-.5 4-1 6M4 14c0 2-.5 4-1 6m4-4c0 2-.5 3-1 4m14-4-1 4"/></>,
  activity: <><path d="M3 12h4l3-8 4 16 3-8h4"/></>,
  arrow: <><path d="M4 12h16m-6-6 6 6-6 6"/></>,
  plus: <path d="M12 5v14M5 12h14"/>,
  search: <><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></>,
  refresh: <><path d="M20 7v5h-5M4 17v-5h5"/><path d="M5 8a8 8 0 0 1 13-3l2 3M4 16l2 3a8 8 0 0 0 13-3"/></>,
  download: <><path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/></>,
  upload: <><path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/></>,
  close: <path d="m6 6 12 12M6 18 18 6"/>,
  lock: <><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 5v2"/></>,
  logout: <><path d="M10 4H4v16h6m-1-8h12m-4-4 4 4-4 4"/></>,
  check: <path d="m5 12 4 4L19 6"/>,
  chevron: <path d="m9 5 7 7-7 7"/>,
  map: <><path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16"/></>,
  menu: <path d="M4 6h16M4 12h16M4 18h16"/>,
};
function Icon({ name, size = 20 }: { name: IconName; size?: number }) { return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name]}</svg>; }
const nav: { id: View; label: string; icon: IconName; subtitle: string }[] = [
  { id: 'overview', label: 'Overview', icon: 'grid', subtitle: 'Uma visão clara. Cada operação rastreável.' },
  { id: 'authorizations', label: 'Autorizações', icon: 'lock', subtitle: 'Responsáveis, comprovação de autoridade, testes permitidos e limites aprovados.' },
  { id: 'assessments', label: 'Avaliações', icon: 'layers', subtitle: 'Planos versionados, etapas autorizadas e resultados rastreáveis.' },
  { id: 'imports', label: 'Universal Import Lab', icon: 'upload', subtitle: 'Quarentena e inspeção de projetos ZIP, TAR e TAR.GZ autorizados.' },
  { id: 'soc', label: 'SOC', icon: 'activity', subtitle: 'Eventos, detecções e incidentes da empresa em contexto.' },
  { id: 'endpoints', label: 'Endpoint Agent', icon: 'shield', subtitle: 'Sensores autenticados e integridade de arquivos selecionados.' },
  { id: 'operations', label: 'Investigar e corrigir', icon: 'fingerprint', subtitle: 'Casos, evidências e correções reversíveis de artefatos no laboratório.' },
  { id: 'analyses', label: 'Análises especializadas', icon: 'search', subtitle: 'Artefatos de rede, dependências, identidade, cloud, IA e perícia.' },
  { id: 'lab', label: 'AttackLab', icon: 'box', subtitle: 'Inventário de portas de alvos explicitamente autorizados no laboratório.' },
  { id: 'forensics', label: 'Perícia offline', icon: 'fingerprint', subtitle: 'Capturas de rede e backups fornecidos, com originais preservados.' },
  { id: 'graph', label: 'RiskGraph', icon: 'layers', subtitle: 'Relações entre ativos, achados, incidentes e evidências da empresa.' },
  { id: 'capabilities', label: 'Matriz de capacidades', icon: 'map', subtitle: 'Cobertura real, referências, dependências e estado de validação V6.9.' },
  { id: 'assets', label: 'Assets', icon: 'box', subtitle: 'Inventário, contexto de risco e autorização explícita.' },
  { id: 'securebuild', label: 'SecureBuild', icon: 'code', subtitle: 'Auditoria estática de arquivos em escopo autorizado.' },
  { id: 'barriers', label: 'BarrierMatrix', icon: 'layers', subtitle: 'Controles independentes. Verificação antes de confiança.' },
  { id: 'evidence', label: 'EvidenceChain', icon: 'fingerprint', subtitle: 'Artefatos preservados. Integridade rastreável.' },
  { id: 'audit', label: 'Audit Logs', icon: 'activity', subtitle: 'Histórico de operações da sua organização.' },
];
const environment: Record<string, string> = { lab: 'Laboratório', staging: 'Homologação', production: 'Produção' };
const kind: Record<string, string> = { application: 'Aplicação', server: 'Servidor', repository: 'Repositório' };
const severityLabel: Record<string, string> = { critical: 'Crítica', high: 'Alta', medium: 'Média', low: 'Baixa', info: 'Informativa', informational: 'Informativa' };
function Badge({ children, tone = '' }: { children: ReactNode; tone?: string }) { return <span className={`badge ${tone}`}>{children}</span>; }
function Empty({ icon = 'box', title, children, action }: { icon?: IconName; title: string; children: ReactNode; action?: ReactNode }) { return <div className="empty"><div className="empty-icon"><Icon name={icon} size={26}/></div><h3>{title}</h3><p>{children}</p>{action}</div>; }
function FormError({ value }: { value: string }) { return value ? <div className="form-error" role="alert">{value}</div> : null; }
function Panel({ title, eyebrow, action, children, className = '' }: { title: string; eyebrow?: string; action?: ReactNode; children: ReactNode; className?: string }) { return <section className={`panel ${className}`}><div className="panel-header"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2></div>{action}</div>{children}</section>; }
function Modal({ title, subtitle, close, children }: { title: string; subtitle: string; close: () => void; children: ReactNode }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { const dialog = ref.current; dialog?.showModal(); return () => dialog?.close(); }, []);
  return <dialog ref={ref} className="modal" onCancel={close} onClick={e => { if (e.target === e.currentTarget) close(); }}><div className="modal-head"><div><span className="eyebrow">COMMAND CENTER</span><h2>{title}</h2><p>{subtitle}</p></div><button className="icon-button" onClick={close} aria-label="Fechar janela"><Icon name="close"/></button></div>{children}</dialog>;
}

function Login({ onLogin, initialError }: { onLogin: (session: Session) => void; initialError: string }) {
  const [error, setError] = useState(initialError); const [busy, setBusy] = useState(false);
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault(); const form = new FormData(e.currentTarget); setBusy(true); setError('');
    try { onLogin(await request<Session>('/auth/login', { method: 'POST', body: { email: form.get('email'), password: form.get('password'), otp: form.get('otp') } })); }
    catch (err) { setError(message(err)); } finally { setBusy(false); }
  }
  return <div className="login-page"><div className="login-brand"><Brand/><div className="login-message"><span className="eyebrow accent">PRIVATE OPERATOR EDITION</span><h1>Clareza para investigar.<br/><em>Controle para proteger.</em></h1><p>Seu centro de operações para auditoria de código, controle de escopo e preservação de evidências.</p><div className="login-orbit" aria-hidden="true"><div className="orbit-ring outer"/><div className="orbit-ring middle"/><div className="orbit-ring inner"/><div className="orbit-core"><Icon name="shield" size={52}/></div><span className="orbit-label one">POLICY GATE</span><span className="orbit-label two">EVIDENCE CHAIN</span><span className="orbit-label three">SECURE BUILD</span></div></div><div className="login-footer">I.See Technologies <span>Protect. Detect. Investigate. Verify.</span></div></div><main className="login-main"><div className="login-form"><span className="pill"><span className="dot"/> ACESSO PRIVADO</span><h2>Bem-vindo ao Sentinel.</h2><p>Entre com sua identidade de operador.</p><form onSubmit={submit}><label>E-mail<input name="email" type="email" autoComplete="username" placeholder="operador@sua-organizacao.com" required autoFocus maxLength={254}/></label><label>Senha<input name="password" type="password" autoComplete="current-password" placeholder="Sua senha de acesso" required maxLength={256}/></label><label>Código do autenticador<input name="otp" type="text" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" minLength={6} maxLength={6} placeholder="000 000" required/><small>Informe os 6 dígitos do seu aplicativo TOTP.</small></label><FormError value={error}/><button className="button primary full" disabled={busy}>{busy ? 'Verificando identidade…' : 'Acessar Command Center'}<Icon name={busy ? 'refresh' : 'arrow'}/></button></form><div className="login-note"><Icon name="lock" size={17}/><span>O acesso exige uma conta provisionada pelo administrador e autenticação multifator.</span></div></div><div className="login-bottom">CYBER DEFENSE COMMAND CENTER <span>v0.2 · Desenvolvimento</span></div></main></div>;
}
function Brand() { return <div className="brand"><div className="brand-mark"><Icon name="shield" size={26}/></div><div><strong>I.See <span>Sentinel</span></strong><small>CYBER DEFENSE</small></div></div>; }

interface Data { overview: Overview | null; assets: Asset[]; findings: RecordData[]; scans: RecordData[]; barriers: RecordData[]; evidence: RecordData[]; audit: RecordData[]; authorizations: RecordData[]; organizations: RecordData[]; projects: RecordData[]; events: RecordData[]; alerts: RecordData[]; incidents: RecordData[] }
const initialData: Data = { overview: null, assets: [], findings: [], scans: [], barriers: [], evidence: [], audit: [], authorizations: [], organizations: [], projects: [], events: [], alerts: [], incidents: [] };

export default function App() {
  const [session, setSession] = useState<Session | null>(null); const [booting, setBooting] = useState(true); const [sessionError, setSessionError] = useState('');
  const [view, setView] = useState<View>('overview'); const [data, setData] = useState<Data>(initialData); const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(false); const [query, setQuery] = useState(''); const [modal, setModal] = useState<'asset' | 'scope' | 'scan' | 'evidence' | 'organization' | 'project' | 'scenario' | null>(null);
  const [detail, setDetail] = useState<{ title: string; item: RecordData } | null>(null); const [notice, setNotice] = useState(''); const [mobile, setMobile] = useState(false);
  const isAdmin = session?.user.role === 'admin';
  const refreshGeneration = useRef(0);
  const [contextBusy, setContextBusy] = useState(false);
  useEffect(() => { let active = true; request<Session>('/auth/session').then(value => { if (active) setSession(value); }).catch(err => { if (active && (!(err instanceof ApiError) || err.status !== 401)) setSessionError(message(err)); }).finally(() => { if (active) setBooting(false); }); return () => { active = false; }; }, []);
  const refresh = useCallback(async () => {
    if (!session) return; const generation = ++refreshGeneration.current; setLoading(true);
    const keys = ['overview', 'assets', 'findings', 'scans', 'barriers', 'evidence', 'audit', 'organizations', 'projects', 'events', 'alerts', 'incidents', ...(session.user.role === 'admin' ? ['authorizations'] : [])] as (keyof Data)[];
    const results = await Promise.allSettled(keys.map(key => request<unknown>(`/${key}`)));
    if (generation !== refreshGeneration.current) return;
    const updates: Partial<Data> = {}; const failures: Record<string, string> = {};
    results.forEach((result, index) => { const key = keys[index]; if (result.status === 'fulfilled') { Object.assign(updates, { [key]: key === 'overview' ? result.value : (result.value as { items?: unknown[] })?.items ?? [] }); } else { failures[key] = message(result.reason); if (result.reason instanceof ApiError && result.reason.status === 401) { setSession(null); setSessionError('Sua sessão expirou. Entre novamente.'); setData(initialData); setDetail(null); setModal(null); } } });
    setData(previous => ({ ...previous, ...updates })); setErrors(failures); setLoading(false);
  }, [session]);
  useEffect(() => { void refresh(); }, [refresh]);
  useEffect(() => { if (!notice) return; const timer = window.setTimeout(() => setNotice(''), 7000); return () => window.clearTimeout(timer); }, [notice]);
  const go = (next: View) => { setView(next); setQuery(''); setMobile(false); };
  async function switchOrganization(organizationId: string) {
    if (!session || contextBusy) return;
    ++refreshGeneration.current; setContextBusy(true); setDetail(null); setModal(null); setData(initialData); setErrors({}); setQuery('');
    try { const next = await request<Session>('/context', { method: 'POST', csrfToken: session.csrfToken, body: { organizationId } }); setSession(next); setNotice(`Contexto alterado para ${next.activeOrganization?.name ?? 'a empresa selecionada'}.`); }
    catch (error) { setNotice(message(error)); await refresh(); }
    finally { setContextBusy(false); }
  }
  async function logout() { try { await request('/auth/logout', { method: 'POST', csrfToken: session?.csrfToken }); ++refreshGeneration.current; setSession(null); setSessionError(''); setData(initialData); setDetail(null); setModal(null); setNotice(''); setErrors({}); } catch (err) { setNotice(message(err)); } }
  async function created(note: string) { setModal(null); setNotice(note); await refresh(); }
  async function download(scan: RecordData) { try { const report = await request<unknown>(`/reports/${encodeURIComponent(text(scan, 'id'))}`); const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `sentinel-report-${text(scan, 'id').replace(/[^a-zA-Z0-9-]/g, '')}.json`; link.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000); } catch (err) { setNotice(message(err)); } }
  async function evidenceDetail(item: RecordData) { try { const full = await request<RecordData>(`/evidence/${encodeURIComponent(text(item, 'id'))}`); setDetail({ title: 'Registro de evidência', item: full }); } catch (err) { setNotice(message(err)); } }
  const filter = <T,>(rows: T[]) => rows.filter(row => JSON.stringify(row).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));
  if (booting) return <div className="boot"><Brand/><span className="loading-text">Verificando sessão…</span></div>;
  if (!session) return <Login onLogin={value => { setData(initialData); setDetail(null); setModal(null); setErrors({}); setSession(value); setView('overview'); setSessionError(''); }} initialError={sessionError}/>;
  const current = nav.find(item => item.id === view);
  const scopeCount = data.authorizations.filter(item => !item.revokedAt && new Date(text(item, 'expiresAt')).getTime() > Date.now()).length;
  return <div className="app-shell"><a className="skip-link" href="#main">Pular para o conteúdo</a><aside className={`sidebar ${mobile ? 'mobile-open' : ''}`}><Brand/><div className="workspace-label"><span className="workspace-avatar">IS</span><div><label className="context-selector"><span className="sr-only">Empresa em contexto</span><select aria-label="Empresa em contexto" value={session.activeOrganization?.id ?? session.user.organizationId} disabled={contextBusy || !data.organizations.length} onChange={event => switchOrganization(event.target.value)}>{data.organizations.length ? data.organizations.map(org => <option key={text(org, 'id')} value={text(org, 'id')}>{text(org, 'name')}</option>) : <option value={session.activeOrganization?.id ?? session.user.organizationId}>{session.activeOrganization?.name ?? 'Empresa atual'}</option>}</select></label><span>Operador fundador · privado</span></div><button className="icon-button" onClick={() => setModal('organization')} aria-label="Adicionar empresa" title="Adicionar empresa"><Icon name="plus" size={15}/></button></div><div className="nav-group-label">COMMAND CENTER</div><nav aria-label="Navegação principal">{nav.map(item => <button key={item.id} onClick={() => go(item.id)} aria-current={view === item.id ? 'page' : undefined} className={`nav-item ${view === item.id ? 'active' : ''}`}><Icon name={item.icon}/><span>{item.label}</span>{view === item.id && <span className="nav-active-dot"/>}</button>)}</nav><div className="nav-divider"/><button className={`nav-item ${view === 'roadmap' ? 'active' : ''}`} onClick={() => go('roadmap')}><Icon name="map"/><span>Evolução da plataforma</span></button><div className="sidebar-bottom"><div className="edition-card"><div><Icon name="layers" size={17}/><span>Private Operator</span></div><p>Desenvolvimento v0.2</p><small>Capacidades verificáveis, em evolução.</small></div><div className="user-card"><div className="avatar">{session.user.email.slice(0, 2).toUpperCase()}</div><div className="user-info"><strong title={session.user.email}>{session.user.email}</strong><span>{isAdmin ? 'Administrador' : session.user.role}</span></div><button className="icon-button" onClick={logout} aria-label="Sair da sessão" title="Sair da sessão"><Icon name="logout" size={17}/></button></div></div></aside>{mobile && <button className="mobile-backdrop" aria-label="Fechar navegação" onClick={() => setMobile(false)}/>}
    <div className="main-shell"><header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-toggle" onClick={() => setMobile(!mobile)} aria-label="Abrir navegação"><Icon name="menu"/></button><span>Workspace</span><Icon name="chevron" size={13}/><strong>{current?.label ?? 'Evolução'}</strong></div><div className="topbar-right"><span className="private-label"><Icon name="lock" size={13}/> Ambiente privado</span><span className="version">V0.2</span></div></header><main id="main" className="main-content"><div className="page-heading"><div><span className="eyebrow">I.SEE SENTINEL / {view === 'overview' ? 'SITUATIONAL AWARENESS' : 'OPERAÇÕES'}</span><h1>{view === 'overview' ? 'Visão operacional' : current?.label ?? 'Evolução da plataforma'}<span className="heading-dot">.</span></h1><p>{current?.subtitle ?? 'O que funciona hoje e o que ainda precisa ser construído.'}</p></div><div className="heading-actions"><button className="button secondary" onClick={refresh} disabled={loading}><span className={loading ? 'spin' : ''}><Icon name="refresh" size={16}/></span>{loading ? 'Atualizando' : 'Atualizar'}</button>{view === 'soc' ? <button className="button primary" onClick={() => setModal('scenario')}><Icon name="activity" size={17}/>Executar cenário de laboratório</button> : view === 'overview' || view === 'securebuild' ? <button className="button primary" onClick={() => setModal('scan')}><Icon name="plus" size={17}/>Nova análise</button> : view === 'assets' ? <button className="button primary" onClick={() => setModal('asset')}><Icon name="plus" size={17}/>Adicionar ativo</button> : view === 'evidence' ? <button className="button primary" onClick={() => setModal('evidence')}><Icon name="upload" size={17}/>Importar evidência</button> : null}</div></div>
      {Object.keys(errors).length > 0 && <div className="error-banner" role="alert"><Icon name="activity" size={18}/><div><strong>Alguns dados não puderam ser atualizados.</strong>{Object.entries(errors).map(([key, value]) => <p key={key}>{key}: {value}</p>)}</div></div>}
      {view === 'overview' && <><div className="source-line"><span className="source-status"><span className={`dot ${data.overview ? '' : 'muted'}`}/>{data.overview ? 'Dados da sua organização' : loading ? 'Carregando dados da organização' : 'Dados indisponíveis'}</span><span>{data.overview ? `Última consulta ${date(data.overview.generatedAt)}` : 'Aguardando API local'}</span></div><div className="metric-grid">{([{ label: 'Ativos cadastrados', value: data.overview?.assets, icon: 'box', note: 'Inventário da organização' }, { label: 'Achados registrados', value: data.overview?.findings, icon: 'search', note: `${data.overview?.highFindings ?? '—'} de severidade alta ou crítica` }, { label: 'Análises executadas', value: data.overview?.scans, icon: 'code', note: 'SecureBuild · análise estática' }, { label: 'Evidências preservadas', value: data.overview?.evidence, icon: 'fingerprint', note: 'Artefatos com hash de integridade' }] as const).map((item, index) => <div className="metric-card" key={item.label}><div className="metric-top"><span>{item.label}</span><Icon name={item.icon} size={19}/></div><div className="metric-value">{item.value ?? '—'}<span className="metric-index">0{index + 1}</span></div><p>{item.note}</p></div>)}</div>
      <div className="overview-grid"><Panel title="Sua próxima operação" eyebrow="WORKFLOW AUTORIZADO" className="operation-panel"><div className="operation-copy"><div className="operation-symbol"><Icon name="shield" size={32}/></div><h3>{data.assets.length ? 'Da análise à evidência.' : 'Visibilidade começa com contexto.'}</h3><p>{data.assets.length ? 'Envie arquivos de um ativo autorizado. Analise o código, revise achados e preserve o resultado da operação.' : 'Cadastre seu primeiro ativo, defina uma autorização de escopo e execute uma análise de segurança.'}</p><button className="text-button accent" onClick={() => data.assets.length ? setModal('scan') : setModal('asset')}>{data.assets.length ? 'Iniciar análise' : 'Cadastrar primeiro ativo'}<Icon name="arrow" size={17}/></button></div><div className="workflow"><div><span>01</span><strong>Definir ativo</strong><small>Contexto e criticidade</small></div><i/><div><span>02</span><strong>Autorizar escopo</strong><small>Operação e validade</small></div><i/><div><span>03</span><strong>Verificar</strong><small>Achados e evidências</small></div></div></Panel><Panel title="Postura das barreiras" eyebrow="BARRIERMATRIX" action={<button className="icon-button" aria-label="Ver BarrierMatrix" onClick={() => go('barriers')}><Icon name="arrow" size={18}/></button>}><div className="barrier-summary"><div className="barrier-graphic"><Icon name="layers" size={38}/><span>14</span><small>CAMADAS PREVISTAS</small></div><div><Badge tone="neutral">Validação por controle</Badge><p>Uma barreira cadastrada não comprova proteção. Consulte o estado observado e as evidências de cada controle.</p><div className="barrier-count"><strong>{data.barriers.length}</strong><span>registros disponíveis</span></div></div></div><div className="panel-foot"><span>Sem percentual de proteção estimado</span><Icon name="lock" size={14}/></div></Panel></div>
      <div className="overview-bottom"><Panel title="Atividade recente" eyebrow="TRILHA OPERACIONAL" action={<button className="text-button" onClick={() => go('audit')}>Ver auditoria<Icon name="arrow" size={15}/></button>}>{data.overview?.recentEvents?.length ? <div className="timeline">{data.overview.recentEvents.slice(0, 5).map((event, i) => <div className="timeline-row" key={text(event, 'id') || i}><span className="timeline-dot"/><div><strong>{text(event, 'action', 'type', 'eventType') || 'Evento registrado'}</strong><small>{text(event, 'actorEmail', 'actorId', 'source') || 'Organização atual'}</small></div>{(event.data as RecordData | undefined)?.synthetic === true && <Badge tone="warning">Sintético · laboratório</Badge>}<time>{date(event.occurredAt ?? event.receivedAt ?? event.createdAt ?? event.timestamp)}</time></div>)}</div> : <Empty icon="activity" title="Nenhuma atividade disponível">As operações registradas aparecerão aqui após a primeira execução.</Empty>}</Panel><Panel title="Limites operacionais" eyebrow="POLICYGATE"><div className="policy-list"><div><Icon name="lock"/><span><strong>Escopo explícito</strong><small>Operações exigem autorização válida.</small></span></div><div><Icon name="fingerprint"/><span><strong>Rastreabilidade</strong><small>Eventos e evidências vinculados à organização.</small></span></div><div><Icon name="code"/><span><strong>Análise de conteúdo</strong><small>O scanner não executa arquivos enviados.</small></span></div></div><div className="panel-foot"><span>{isAdmin ? `${scopeCount} autorizações dentro da validade` : 'Acesso conforme seu papel'}</span><button className="text-button" onClick={() => go('assets')}>Gerenciar<Icon name="arrow" size={14}/></button></div></Panel></div></>}
      {view === 'assets' && <><div className="section-toolbar"><Search value={query} change={setQuery} placeholder="Buscar nome, tipo ou ambiente…"/><div className="toolbar-actions"><span className="result-count">{data.assets.length} ativos · {data.projects.length} projetos</span><button className="button secondary" onClick={() => setModal('project')}><Icon name="plus" size={16}/>Criar projeto</button>{isAdmin && <button className="button secondary" onClick={() => setModal('scope')}><Icon name="lock" size={16}/>Autorizar escopo</button>}</div></div><Panel title="Inventário de ativos" action={<Badge>ORGANIZAÇÃO ATUAL</Badge>}>{filter(data.assets).length ? <div className="table-scroll"><table><thead><tr><th>Ativo</th><th>Tipo</th><th>Ambiente</th><th>Criticidade</th><th>Cadastrado</th></tr></thead><tbody>{filter(data.assets).map(asset => <tr key={asset.id}><td><div className="cell-title"><span className="table-icon"><Icon name="box" size={17}/></span><div><strong>{asset.name}</strong><small className="mono">{asset.id.slice(0, 12)}</small></div></div></td><td>{kind[asset.kind] ?? asset.kind}</td><td><Badge tone={asset.environment === 'production' ? 'warning' : ''}>{environment[asset.environment] ?? asset.environment}</Badge></td><td><span className="criticality" aria-label={`Criticidade ${asset.criticality} de 5`}>{[1, 2, 3, 4, 5].map(n => <i key={n} className={n <= asset.criticality ? 'filled' : ''}/>)}</span><span className="muted-text"> {asset.criticality}/5</span></td><td className="muted-text">{date(asset.createdAt)}</td></tr>)}</tbody></table></div> : <Empty title={query ? 'Nenhum ativo encontrado' : 'Seu inventário começa aqui'}>Cadastre aplicações, servidores e repositórios que pertencem ao seu escopo autorizado.</Empty>}</Panel>{isAdmin && <Panel title="Autorizações de operação" eyebrow="ESCOPO E VALIDADE" className="section-gap">{data.authorizations.length ? <div className="table-scroll"><table><thead><tr><th>Referência</th><th>Ativo</th><th>Operações</th><th>Validade</th><th>Estado</th></tr></thead><tbody>{data.authorizations.map(item => <tr key={text(item, 'id')}><td className="mono">{text(item, 'authorizationRef') || '—'}</td><td>{data.assets.find(asset => asset.id === item.assetId)?.name ?? text(item, 'assetId')}</td><td>{Array.isArray(item.operations) ? item.operations.join(', ') : '—'}</td><td>{date(item.expiresAt)}</td><td><Badge tone={!item.revokedAt && new Date(text(item, 'expiresAt')).getTime() > Date.now() ? 'positive' : 'neutral'}>{item.revokedAt ? 'Revogada' : new Date(text(item, 'expiresAt')).getTime() > Date.now() ? 'Dentro da validade' : 'Expirada'}</Badge></td></tr>)}</tbody></table></div> : <Empty icon="lock" title="Nenhum escopo autorizado">Defina o ativo, a operação permitida, a referência de autorização e o prazo antes de executar.</Empty>}</Panel>}</>}
      {view === 'securebuild' && <><div className="info-strip"><Icon name="code" size={19}/><span>Análise estática local de arquivos enviados. Achados heurísticos exigem revisão técnica; ausência de achados não comprova segurança.</span></div><div className="section-toolbar"><Search value={query} change={setQuery} placeholder="Buscar achados, regras ou arquivos…"/><span className="result-count">{data.findings.length} achados</span></div><Panel title="Achados de segurança" action={<Badge>SECUREBUILD</Badge>}>{filter(data.findings).length ? <div className="table-scroll"><table><thead><tr><th>Achado</th><th>Severidade</th><th>Localização</th><th>Regra</th><th>Detalhes</th></tr></thead><tbody>{filter(data.findings).map((finding, i) => <tr key={text(finding, 'id') || i}><td><strong>{text(finding, 'title', 'message') || 'Achado de segurança'}</strong></td><td><Badge tone={text(finding, 'severity')}>{severityLabel[text(finding, 'severity')] ?? text(finding, 'severity')}</Badge></td><td className="mono">{text(finding, 'file', 'path', 'filePath') || '—'}{finding.line ? `:${finding.line}` : ''}</td><td className="mono">{text(finding, 'ruleId', 'rule') || '—'}</td><td><button className="text-button" onClick={() => setDetail({ title: 'Detalhes do achado', item: finding })}>Inspecionar<Icon name="arrow" size={14}/></button></td></tr>)}</tbody></table></div> : <Empty icon="code" title={query ? 'Nenhum achado correspondente' : 'Nenhum achado registrado'}>Envie arquivos de um projeto autorizado para executar a primeira auditoria estática.</Empty>}</Panel><Panel title="Histórico de análises" eyebrow="EXECUÇÕES E RELATÓRIOS" className="section-gap">{data.scans.length ? <div className="table-scroll"><table><thead><tr><th>Execução</th><th>Ativo</th><th>Estado</th><th>Data</th><th>Relatório</th></tr></thead><tbody>{data.scans.map(scan => <tr key={text(scan, 'id')}><td className="mono">{text(scan, 'id').slice(0, 16)}</td><td>{data.assets.find(asset => asset.id === scan.assetId)?.name ?? text(scan, 'assetId')}</td><td><Badge>{text(scan, 'status') || 'Registrada'}</Badge></td><td>{date(scan.createdAt ?? scan.completedAt)}</td><td><button className="text-button" onClick={() => download(scan)}><Icon name="download" size={15}/>JSON</button></td></tr>)}</tbody></table></div> : <Empty icon="activity" title="Nenhuma análise executada">Os relatórios das suas execuções ficarão disponíveis aqui.</Empty>}</Panel></>}
      {view === 'barriers' && <><div className="info-strip"><Icon name="layers" size={19}/><span>Estados referem-se aos controles observados pelo Sentinel. Não representam proteção global nem validação independente da infraestrutura.</span></div><Panel title="Registro de controles" action={<Badge>DEFESA EM PROFUNDIDADE</Badge>}>{data.barriers.length ? <div className="barrier-list">{data.barriers.map((barrier, index) => <article className="barrier-item" key={text(barrier, 'assetId') + ':' + (text(barrier, 'id') || index)}><span className="layer-number">{String(index + 1).padStart(2, '0')}</span><div><h3>{text(barrier, 'name', 'title', 'controlId') || `Controle ${index + 1}`}</h3><p>{text(barrier, 'description', 'objective') || 'Consulte o registro para conhecer o objetivo e os critérios de verificação.'}</p><small>{data.assets.find(asset => asset.id === barrier.assetId)?.name ?? 'Ativo não informado'} · {date(barrier.evaluatedAt ?? barrier.createdAt)} · {text(barrier, 'layer', 'category') || 'Controle de segurança'}</small></div><Badge tone={text(barrier, 'status') === 'fail' ? 'warning' : 'neutral'}>{text(barrier, 'status') === 'fail' ? 'Falha no snapshot' : text(barrier, 'status') === 'not_evaluated' ? 'Não avaliada em execução' : text(barrier, 'status', 'state') || 'Não verificado'}</Badge><button className="icon-button" onClick={() => setDetail({ title: 'Registro de controle', item: barrier })} aria-label={`Inspecionar ${text(barrier, 'name', 'title')}`}><Icon name="arrow" size={18}/></button></article>)}</div> : <Empty icon="layers" title="Nenhuma verificação de barreira registrada">Os controles disponíveis serão exibidos conforme a API registrar seus estados e evidências.</Empty>}</Panel><div className="plain-note">As 14 camadas fazem parte da arquitetura planejada. Somente os controles acima possuem registro nesta instalação.</div></>}
      {view === 'evidence' && <><div className="section-toolbar"><Search value={query} change={setQuery} placeholder="Buscar evidência, hash ou tipo…"/><span className="result-count">{data.evidence.length} registros</span></div><Panel title="Repositório de evidências" action={<Badge>INTEGRIDADE E CUSTÓDIA</Badge>}>{filter(data.evidence).length ? <div className="table-scroll"><table><thead><tr><th>Artefato</th><th>SHA-256</th><th>Tipo</th><th>Registro</th><th>Inspecionar</th></tr></thead><tbody>{filter(data.evidence).map(item => <tr key={text(item, 'id')}><td><div className="cell-title"><span className="table-icon teal"><Icon name="fingerprint" size={18}/></span><strong>{text(item, 'name', 'filename') || 'Evidência'}</strong></div></td><td className="mono hash-cell" title={text(item, 'sha256', 'hash')}>{text(item, 'sha256', 'hash') || '—'}</td><td>{text(item, 'mediaType', 'mimeType') || '—'}</td><td>{date(item.createdAt)}</td><td><button className="text-button" onClick={() => evidenceDetail(item)}>Ver registro<Icon name="arrow" size={14}/></button></td></tr>)}</tbody></table></div> : <Empty icon="fingerprint" title={query ? 'Nenhuma evidência correspondente' : 'Nenhum artefato preservado'}>Importe um arquivo autorizado ou execute uma análise para iniciar a trilha de evidências.</Empty>}</Panel><div className="plain-note">O hash verifica integridade do conteúdo. A força probatória depende também dos procedimentos de coleta, acesso, retenção e custódia.</div></>}
      {view === 'audit' && <><div className="section-toolbar"><Search value={query} change={setQuery} placeholder="Buscar ação, operador ou recurso…"/><span className="result-count">{data.audit.length} eventos retornados</span></div><Panel title="Trilha de auditoria" action={<Badge>ORGANIZAÇÃO ATUAL</Badge>}>{filter(data.audit).length ? <div className="table-scroll"><table><thead><tr><th>Data</th><th>Operação</th><th>Ator</th><th>Recurso</th><th>Registro</th></tr></thead><tbody>{filter(data.audit).map((event, i) => <tr key={text(event, 'id') || i}><td>{date(event.occurredAt ?? event.receivedAt ?? event.createdAt ?? event.timestamp)}</td><td><span className="event-action"><span className="dot"/>{text(event, 'action', 'type') || 'Evento'}</span></td><td className="mono">{text(event, 'actorEmail', 'actorId', 'userId') || 'Sistema'}</td><td className="mono">{text(event, 'resourceId', 'targetId', 'resourceType') || '—'}</td><td><button className="icon-button" onClick={() => setDetail({ title: 'Evento de auditoria', item: event })} aria-label="Inspecionar evento"><Icon name="arrow" size={17}/></button></td></tr>)}</tbody></table></div> : <Empty icon="activity" title={query ? 'Nenhum evento correspondente' : 'Nenhum evento disponível'}>A trilha registra as operações realizadas dentro da organização.</Empty>}</Panel></>}
      {view === 'soc' && <SocPanel data={data} query={query} setQuery={setQuery} inspect={item => setDetail({ title: 'Registro SOC', item })}/>}
      {view === 'endpoints' && !contextBusy && <EndpointView key={session.user.organizationId} session={session} assets={data.assets} onChanged={()=>void refresh()}/>}
      {view === 'operations' && !contextBusy && <OperationsView key={session.user.organizationId} session={session} assets={data.assets} incidents={data.incidents} onChanged={()=>void refresh()}/>}
      {view === 'capabilities' && <CapabilityView/>}
      {view === 'lab' && !contextBusy && <LabView key={session.user.organizationId} session={session} assets={data.assets} onChanged={()=>void refresh()}/>}
      {view === 'analyses' && !contextBusy && <AnalysisView key={session.user.organizationId} session={session} assets={data.assets} onChanged={()=>void refresh()}/>}
      {view === 'forensics' && !contextBusy && <ForensicView key={session.user.organizationId} session={session} assets={data.assets} onChanged={()=>void refresh()}/>}
      {view === 'imports' && !contextBusy && <ImportView key={session.user.organizationId} session={session} assets={data.assets} onChanged={()=>void refresh()}/>}
      {view === 'authorizations' && !contextBusy && <AuthorizationView key={session.user.organizationId} session={session} assets={data.assets} projects={data.projects} onChanged={()=>void refresh()}/>}
      {view === 'assessments' && !contextBusy && <AssessmentView key={session.user.organizationId} session={session} assets={data.assets} projects={data.projects} onChanged={()=>void refresh()}/>}
      {view === 'graph' && !contextBusy && <RiskGraphView key={session.user.organizationId}/>}
      {view === 'roadmap' && <Roadmap/>}
      <footer className="main-footer"><span>I.See Technologies <i/> Sentinel Private Operator Edition</span><span>Protect. Detect. Investigate. Verify.</span></footer>
    </main></div><div className="toast-region" aria-live="polite" aria-atomic="true">{notice && <div className="toast"><Icon name="activity" size={18}/><span>{notice}</span><button className="icon-button" onClick={() => setNotice('')} aria-label="Dispensar aviso"><Icon name="close" size={16}/></button></div>}</div>
    {modal === 'asset' && <Modal title="Cadastrar ativo" subtitle="Registre o contexto antes de autorizar operações." close={() => setModal(null)}><AssetForm session={session} projects={data.projects} done={() => created('Ativo cadastrado. Defina uma autorização para executar operações.')}/></Modal>}
    {modal === 'scope' && <Modal title="Autorizar escopo" subtitle="Uma autorização permite apenas as operações e a validade definidas." close={() => setModal(null)}><ScopeForm session={session} assets={data.assets} done={() => created('Autorização de escopo registrada.')}/></Modal>}
    {modal === 'scan' && <Modal title="Nova análise SecureBuild" subtitle="Selecione arquivos de um projeto que você está autorizado a auditar." close={() => setModal(null)}><ScanForm session={session} assets={data.assets} done={async () => { go('securebuild'); await created('Análise concluída. Revise os achados e baixe o relatório.'); }}/></Modal>}
    {modal === 'evidence' && <Modal title="Importar evidência" subtitle="O arquivo será associado ao ativo autorizado e receberá um hash de integridade." close={() => setModal(null)}><EvidenceForm session={session} assets={data.assets} done={() => created('Evidência importada e registrada.')}/></Modal>}
    {modal === 'organization' && <Modal title="Adicionar empresa" subtitle="A empresa define um contexto de dados. Nenhuma conta de cliente será criada." close={() => setModal(null)}><ContextForm kind="organization" session={session} done={() => created('Empresa cadastrada. Selecione-a no contexto para trabalhar com seus dados.')}/></Modal>}
    {modal === 'project' && <Modal title="Criar projeto" subtitle={`Empresa em contexto: ${session.activeOrganization?.name ?? 'empresa atual'}.`} close={() => setModal(null)}><ContextForm kind="project" session={session} done={() => created('Projeto registrado na empresa em contexto.')}/></Modal>}
    {modal === 'scenario' && <Modal title="Cenário sintético de laboratório" subtitle="Valide a detecção de falhas de autenticação com eventos explicitamente sintéticos." close={() => setModal(null)}><ScenarioForm session={session} assets={data.assets} done={() => created('Cenário enviado. Consulte os alertas persistidos e seus eventos de origem.')}/></Modal>}
    {detail && <Modal title={detail.title} subtitle="Conteúdo retornado pelo registro da organização." close={() => setDetail(null)}><div className="detail-body">{text(detail.item, 'description', 'recommendation') && <p>{text(detail.item, 'description', 'recommendation')}</p>}<pre>{JSON.stringify(detail.item, null, 2)}</pre></div></Modal>}
  </div>;
}

function Search({ value, change, placeholder }: { value: string; change: (value: string) => void; placeholder: string }) { return <label className="search-box"><Icon name="search" size={17}/><input value={value} onChange={event => change(event.target.value)} placeholder={placeholder} aria-label={placeholder}/>{value && <button className="icon-button" type="button" onClick={() => change('')} aria-label="Limpar busca"><Icon name="close" size={14}/></button>}</label>; }
type FormProps = { session: Session; done: () => Promise<void> }; type AssetFormProps = FormProps & { assets: Asset[] };
function AssetSelect({ assets }: { assets: Asset[] }) { return <label>Ativo autorizado<select name="assetId" required defaultValue=""><option value="" disabled>Selecione um ativo</option>{assets.map(asset => <option value={asset.id} key={asset.id}>{asset.name} · {environment[asset.environment] ?? asset.environment}</option>)}</select>{!assets.length && <small>Cadastre um ativo em Assets antes de continuar.</small>}</label>; }
function AssetForm({ session, done, projects }: FormProps & { projects: RecordData[] }) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); setBusy(true); setError(''); try { await request('/assets', { method: 'POST', csrfToken: session.csrfToken, body: { name: data.get('name'), kind: data.get('kind'), environment: data.get('environment'), criticality: Number(data.get('criticality')), ...(data.get('projectId') ? { projectId: data.get('projectId') } : {}) } }); await done(); } catch (err) { setError(message(err)); } finally { setBusy(false); } }
  return <form className="modal-form" onSubmit={submit}><label>Nome do ativo<input name="name" placeholder="Ex.: API de faturamento" required minLength={2} maxLength={120} autoFocus/></label><div className="form-row"><label>Tipo<select name="kind" defaultValue="application"><option value="application">Aplicação</option><option value="server">Servidor</option><option value="repository">Repositório</option></select></label><label>Ambiente<select name="environment" defaultValue="lab"><option value="lab">Laboratório</option><option value="staging">Homologação</option><option value="production">Produção</option></select></label></div><label>Criticidade<select name="criticality" defaultValue="3"><option value="1">1 — Baixa</option><option value="2">2 — Moderada</option><option value="3">3 — Relevante</option><option value="4">4 — Alta</option><option value="5">5 — Crítica</option></select></label><label>Projeto<select name="projectId" defaultValue=""><option value="">Sem projeto vinculado</option>{projects.map(project => <option key={text(project, 'id')} value={text(project, 'id')}>{text(project, 'name')}</option>)}</select></label><p className="form-hint">O cadastro não concede autorização de análise. Um administrador deve registrar um escopo válido para cada operação.</p><FormError value={error}/><button className="button primary full" disabled={busy}>{busy ? 'Cadastrando…' : 'Cadastrar ativo'}<Icon name="plus" size={17}/></button></form>;
}
function ScopeForm({ session, assets, done }: AssetFormProps) {
  const legacyAssets = assets.filter(asset => asset.authorizationMode !== 'managed');
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); setBusy(true); setError(''); try { const operations = data.getAll('operations'); if (!operations.length) throw new Error('Selecione ao menos uma operação.'); const expires = new Date(String(data.get('expiresAt'))); if (expires.getTime() <= Date.now()) throw new Error('A validade precisa estar no futuro.'); await request('/authorizations', { method: 'POST', csrfToken: session.csrfToken, body: { assetId: data.get('assetId'), authorizationRef: data.get('authorizationRef'), operations, expiresAt: expires.toISOString() } }); await done(); } catch (err) { setError(message(err)); } finally { setBusy(false); } }
  return <form className="modal-form" onSubmit={submit}><AssetSelect assets={legacyAssets}/><p className="form-hint">Ativos controlados por perfis são gerenciados na área Autorizações e não aparecem neste formulário. Uma nova autorização de avaliação exige revisão e aprovação.</p><label>Referência da autorização<input name="authorizationRef" placeholder="Ex.: contrato, chamado ou termo de autorização" required minLength={3} maxLength={200}/><small>Use uma referência verificável ao consentimento do responsável.</small></label><fieldset><legend>Operações permitidas</legend><label className="checkbox-label"><input type="checkbox" name="operations" value="scan" defaultChecked/>Análise estática (scan)</label><label className="checkbox-label"><input type="checkbox" name="operations" value="evidence.import"/>Importação de evidências</label><label className="checkbox-label"><input type="checkbox" name="operations" value="event.ingest"/>Ingestão de eventos pela API</label></fieldset><label>Válida até · horário local<input name="expiresAt" type="datetime-local" required/></label><FormError value={error}/><button className="button primary full" disabled={busy || !legacyAssets.length}>{busy ? 'Registrando…' : 'Registrar autorização'}<Icon name="lock" size={17}/></button></form>;
}
function ScanForm({ session, assets, done }: AssetFormProps) {
  const [files, setFiles] = useState<File[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); setBusy(true); setError(''); try { if (!files.length) throw new Error('Selecione ao menos um arquivo.'); if (files.length > 40 || files.some(file => file.size > 256 * 1024) || files.reduce((total, file) => total + file.size, 0) > 1024 * 1024) throw new Error('Limite: 40 arquivos, 256 KiB por arquivo e 1 MiB no total.'); const content = await Promise.all(files.map(async file => ({ path: file.webkitRelativePath || file.name, content: await file.text() }))); if (new Set(content.map(file => file.path)).size !== content.length) throw new Error('Há nomes de arquivo repetidos. Selecione arquivos com nomes únicos.'); if (content.some(file => file.content.includes('\u0000'))) throw new Error('Envie apenas arquivos de texto. Um dos arquivos parece ser binário.'); await request('/scans', { method: 'POST', csrfToken: session.csrfToken, body: { assetId: data.get('assetId'), files: content } }); await done(); } catch (err) { setError(message(err)); } finally { setBusy(false); } }
  return <form className="modal-form" onSubmit={submit}><AssetSelect assets={assets}/><label className="file-picker"><Icon name="upload" size={28}/><strong>Selecione arquivos do projeto</strong><span>Código e configurações em texto · até 40 arquivos</span><input type="file" multiple onChange={event => setFiles(Array.from(event.target.files ?? []))} required aria-label="Arquivos para análise estática"/></label>{files.length > 0 && <div className="selected-files">{files.map((file, index) => <div key={`${file.name}-${index}`}><Icon name="code" size={14}/><span>{file.name}</span><small>{(file.size / 1024).toFixed(1)} KiB</small></div>)}</div>}<p className="form-hint">Requer autorização <code>scan</code> válida. Os conteúdos selecionados são enviados à API local. Revise os arquivos para evitar o envio desnecessário de informações sensíveis.</p><FormError value={error}/><button className="button primary full" disabled={busy || !assets.length}>{busy ? 'Analisando arquivos…' : 'Executar análise'}<Icon name={busy ? 'refresh' : 'arrow'} size={17}/></button></form>;
}
function EvidenceForm({ session, assets, done }: AssetFormProps) {
  const [file, setFile] = useState<File | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const data = new FormData(event.currentTarget); setBusy(true); setError(''); try { if (!file) throw new Error('Selecione um arquivo de evidência.'); if (file.size > 1024 * 1024) throw new Error('A evidência deve ter no máximo 1 MiB.'); const contentBase64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result).split(',')[1]); reader.onerror = () => reject(new Error('Não foi possível ler o arquivo.')); reader.readAsDataURL(file); }); await request('/evidence', { method: 'POST', csrfToken: session.csrfToken, body: { assetId: data.get('assetId'), name: file.name, contentBase64, mediaType: file.type || 'application/octet-stream' } }); await done(); } catch (err) { setError(message(err)); } finally { setBusy(false); } }
  return <form className="modal-form" onSubmit={submit}><AssetSelect assets={assets}/><label className="file-picker"><Icon name="fingerprint" size={28}/><strong>{file?.name ?? 'Selecionar artefato original'}</strong><span>{file ? `${(file.size / 1024).toFixed(1)} KiB` : 'Um arquivo · até 1 MiB'}</span><input type="file" required onChange={event => setFile(event.target.files?.[0] ?? null)} aria-label="Arquivo de evidência"/></label><p className="form-hint">Requer autorização <code>evidence.import</code> válida. O arquivo será importado como conteúdo, sem execução. O registro não substitui um procedimento forense validado.</p><FormError value={error}/><button className="button primary full" disabled={busy || !assets.length}>{busy ? 'Preservando artefato…' : 'Importar evidência'}<Icon name="upload" size={17}/></button></form>;
}
function ContextForm({ session, done, kind: contextKind }: FormProps & { kind: 'organization' | 'project' }) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const values = new FormData(event.currentTarget); setBusy(true); setError('');
    try { await request(contextKind === 'organization' ? '/organizations' : '/projects', { method: 'POST', csrfToken: session.csrfToken, body: { name: values.get('name'), ...(contextKind === 'project' ? { contractRef: values.get('contractRef') } : {}) } }); await done(); }
    catch (error) { setError(message(error)); } finally { setBusy(false); }
  }
  return <form className="modal-form" onSubmit={submit}><label>{contextKind === 'organization' ? 'Nome da empresa' : 'Nome do projeto'}<input name="name" required minLength={2} maxLength={120} autoFocus placeholder={contextKind === 'organization' ? 'Ex.: Empresa de demonstração' : 'Ex.: Auditoria da aplicação web'}/></label>{contextKind === 'project' && <label>Referência contratual<input name="contractRef" required minLength={3} maxLength={200} placeholder="Contrato, ordem de serviço ou referência interna"/></label>}<p className="form-hint">O fundador permanece como operador único. O contexto separa os dados de cada empresa; cadastrar uma empresa ou projeto não autoriza operações sobre ativos.</p><FormError value={error}/><button className="button primary full" disabled={busy}>{busy ? 'Registrando…' : contextKind === 'organization' ? 'Cadastrar empresa' : 'Criar projeto'}<Icon name="plus" size={17}/></button></form>;
}
function ScenarioForm({ session, assets, done }: AssetFormProps) {
  const labs = assets.filter(asset => asset.environment === 'lab');
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [progress, setProgress] = useState(0);
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const values = new FormData(event.currentTarget); setBusy(true); setError(''); setProgress(0); let sent = 0;
    try {
      const assetId = String(values.get('assetId')); if (!labs.some(asset => asset.id === assetId)) throw new Error('Selecione um ativo de laboratório.');
      const subject = `validation-${crypto.randomUUID()}`;
      for (let index = 0; index < 5; index++) {
        await request('/events', { method: 'POST', csrfToken: session.csrfToken, body: { externalId: crypto.randomUUID(), assetId, schemaVersion: 1, type: 'auth.failure', source: 'validation-lab', occurredAt: new Date().toISOString(), data: { subject, synthetic: true } } });
        sent++; setProgress(sent);
      }
      await done();
    } catch (error) { setError(`${sent} de 5 eventos enviados. ${message(error)} Os eventos já aceitos permanecem registrados.`); }
    finally { setBusy(false); }
  }
  return <form className="modal-form" onSubmit={submit}><AssetSelect assets={labs}/><div className="scenario-explanation"><Badge tone="warning">CENÁRIO SINTÉTICO</Badge><h3>5 falhas de autenticação correlacionadas</h3><p>Envia cinco eventos sintéticos com o mesmo sujeito para validar a regra de detecção. Cada evento tem um identificador exclusivo. A API avalia o padrão e pode persistir um alerta e um incidente vinculados.</p><p>Este cenário não executa ataques nem testa a autenticação do ativo.</p></div><p className="form-hint">Requer um ativo de laboratório e autorização <code>event.ingest</code> válida. O painel identifica os dados como sintéticos e mantém a origem <code>validation-lab</code>.</p><FormError value={error}/><button className="button primary full" disabled={busy || !labs.length}>{busy ? `Enviando ${progress}/5 eventos…` : 'Enviar 5 eventos sintéticos'}<Icon name="activity" size={17}/></button></form>;
}
function SocPanel({ data, query, setQuery, inspect }: { data: Data; query: string; setQuery: (value: string) => void; inspect: (item: RecordData) => void }) {
  const filtered = (rows: RecordData[]) => rows.filter(row => JSON.stringify(row).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));
  const assetName = (item: RecordData) => data.assets.find(asset => asset.id === item.assetId)?.name ?? text(item, 'assetId');
  const synthetic = (item: RecordData) => item.synthetic === true || (item.data && typeof item.data === 'object' && (item.data as RecordData).synthetic === true);
  return <><div className="info-strip"><Icon name="activity" size={19}/><span>Eventos e detecções persistidos na empresa em contexto. Cenários de laboratório são identificados como sintéticos e não comprovam cobertura de monitoramento em produção.</span></div><div className="soc-metrics"><div><strong>{data.events.length}</strong><span>Eventos retornados</span></div><div><strong>{data.alerts.length}</strong><span>Alertas persistidos</span></div><div><strong>{data.incidents.length}</strong><span>Incidentes registrados</span></div><div><strong>{data.alerts.filter(synthetic).length}</strong><span>Alertas sintéticos</span></div></div><div className="section-toolbar"><Search value={query} change={setQuery} placeholder="Buscar regra, evento, ativo ou severidade…"/><span className="result-count">Origem: API da empresa em contexto</span></div><Panel title="Alertas de detecção" action={<Badge>REGRAS E EVIDÊNCIAS</Badge>}>{filtered(data.alerts).length ? <div className="table-scroll"><table><thead><tr><th>Alerta</th><th>Ativo</th><th>Severidade</th><th>Origem</th><th>Registro</th><th>Detalhes</th></tr></thead><tbody>{filtered(data.alerts).map(item => <tr key={text(item, 'id')}><td><strong>{text(item, 'title') || text(item, 'ruleId')}</strong><small className="cell-subtitle mono">{text(item, 'ruleId')} · v{text(item, 'ruleVersion') || '1'} · {text(item, 'status')}</small></td><td>{assetName(item)}</td><td><Badge tone={text(item, 'severity')}>{severityLabel[text(item, 'severity')] ?? text(item, 'severity')}</Badge></td><td><Badge tone={synthetic(item) ? 'warning' : 'neutral'}>{synthetic(item) ? 'Sintético · laboratório' : 'Evento ingerido'}</Badge></td><td>{date(item.createdAt)}</td><td><button className="text-button" onClick={() => inspect(item)}>Inspecionar<Icon name="arrow" size={14}/></button></td></tr>)}</tbody></table></div> : <Empty icon="activity" title={query ? 'Nenhum alerta correspondente' : 'Nenhum alerta persistido'}>Uma regra de detecção precisa encontrar seu padrão nos eventos ingeridos. Você pode validar o fluxo com um cenário sintético autorizado.</Empty>}</Panel><Panel title="Eventos de origem" eyebrow="DADOS INGERIDOS" className="section-gap">{filtered(data.events).length ? <div className="table-scroll"><table><thead><tr><th>Evento</th><th>Ativo</th><th>Fonte</th><th>Natureza</th><th>Ocorrência</th><th>Registro</th></tr></thead><tbody>{filtered(data.events).map(item => <tr key={text(item, 'id')}><td className="mono">{text(item, 'type')}</td><td>{assetName(item)}</td><td className="mono">{text(item, 'source')}</td><td><Badge tone={synthetic(item) ? 'warning' : 'neutral'}>{synthetic(item) ? 'Sintético' : 'Ingerido'}</Badge></td><td>{date(item.occurredAt ?? item.createdAt)}</td><td><button className="icon-button" aria-label="Inspecionar evento SOC" onClick={() => inspect(item)}><Icon name="arrow" size={17}/></button></td></tr>)}</tbody></table></div> : <Empty icon="activity" title="Nenhum evento disponível">Eventos recebidos pela API aparecerão aqui com sua origem e horário de ocorrência.</Empty>}</Panel><Panel title="Incidentes" eyebrow="INVESTIGAÇÃO" className="section-gap">{filtered(data.incidents).length ? <div className="table-scroll"><table><thead><tr><th>Incidente</th><th>Ativo</th><th>Estado</th><th>Natureza</th><th>Data</th><th>Detalhes</th></tr></thead><tbody>{filtered(data.incidents).map(item => <tr key={text(item, 'id')}><td><strong>{text(item, 'title') || text(item, 'id')}</strong></td><td>{assetName(item)}</td><td><Badge>{text(item, 'status') || 'Registrado'}</Badge></td><td><Badge tone={synthetic(item) ? 'warning' : 'neutral'}>{synthetic(item) ? 'Sintético' : 'Evento ingerido'}</Badge></td><td>{date(item.createdAt)}</td><td><button className="text-button" onClick={() => inspect(item)}>Inspecionar<Icon name="arrow" size={14}/></button></td></tr>)}</tbody></table></div> : <Empty icon="shield" title="Nenhum incidente registrado">Os incidentes vinculados às detecções da organização aparecerão nesta lista.</Empty>}</Panel></>;
}
function Roadmap() {
  const groups = [
    ['Fundação', 'Command Center, identidade, escopos, ativos e auditoria.', 'Implementação inicial'],
    ['Análise', 'SecureBuild estático, priorização de achados e registro de evidências.', 'Implementação inicial'],
    ['Defesa', 'AutoDefense, SecureFix, DefenseFlow e Self-Healing.', 'Planejado'],
    ['Investigação', 'DeepTrace, NetworkTrace, MalwareLens e IntelScope.', 'Planejado'],
    ['Laboratório', 'AttackLab, PurpleMatrix e simulações isoladas.', 'Planejado'],
    ['Expansão', 'MobileScope, CryptoGuard, ThreatPulse e integrações.', 'Planejado'],
  ];
  return <><div className="info-strip"><Icon name="map" size={20}/><span>Esta edição entrega a fundação operacional. Capacidades planejadas não estão disponíveis e não representam cobertura de segurança.</span></div><div className="roadmap-grid">{groups.map(([title, description, state], i) => <article className="panel roadmap-card" key={title}><div><span className="eyebrow">FASE 0{i + 1}</span><Badge tone={state === 'Planejado' ? 'neutral' : 'positive'}>{state}</Badge></div><h2>{title}</h2><p>{description}</p><small>{state === 'Planejado' ? 'Não implementado nesta versão' : 'Requer validação no ambiente de operação'}</small></article>)}</div><Panel title="Critério de evolução" className="section-gap"><div className="roadmap-note">Implementação não equivale a validação independente. Cada nova capacidade deverá demonstrar um fluxo real, autorização, evidências e testes reproduzíveis antes de ser considerada pronta para operação interna ou comercialização.</div></Panel></>;
}
